   {
    "n": 2,
    "title": "Brown the beef",
    "text": "Heat the oil in a sauté pan over medium-high, brown the beef on all sides in 3–5 minutes, and set it aside."
   },
   {
    "n": 3,
    "title": "Mushrooms and roux",
    "text": "Melt the butter in the same pan over medium heat, season the mushrooms, and cook them until browned, 7–8 minutes. Stir in the tomato paste, rosemary and garlic for a minute, then the flour for one more."
   },
   {
    "n": 4,
    "title": "Deglaze",
    "text": "Pour in the brandy and scrape the pan clean, then whisk in the broth until it's smooth."
   },
   {
    "n": 5,
    "title": "Simmer the filling",
    "text": "Add the potatoes and beef, bring it to a boil, then drop to medium and simmer covered for about 20 minutes, until beef and potato are nearly tender. Stir through the mixed vegetables, onions, parsley and red wine vinegar."
   },
   {
    "n": 6,
    "title": "Cut the lids",
    "text": "Meanwhile cut the puff pastry to fit two 2-cup ovenproof bowls with a ¼-inch overhang — cut shapes from the offcuts if you like — and chill until needed."
   },
   {
    "n": 7,
    "title": "Cap the pies",
    "text": "Ladle the stew into the bowls, lay the pastry over, and stretch and press the edges down over the lip. Egg-wash, add any cut-outs, egg-wash again, and cut a few vents. Set them on the foiled sheet."
   },
   {
    "n": 8,
    "title": "Bake",
    "text": "Bake 30–40 minutes, until the filling bubbles and the crust is golden; tent with foil if it colours too fast. Rest 10 minutes before serving."
   }
