/** Lookup by the slug id used in data/authored-steps.json. */
export const sourceRecipeById = (id) => SOURCE_RECIPES.find((r) => r.id === id) ?? null;

/** Every cuisine present in the library, sorted. */
export const SOURCE_CUISINES = [...new Set(SOURCE_RECIPES.map((r) => r.cuisine))].sort();

/**
 * Loose title match, used to see whether a calendar meal already has a real
 * recipe in the library before we spend an API call generating one.
 */
export function findSourceRecipe(mealName) {
  if (!mealName) return null;
  const norm = (s) => s.toLowerCase().replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();
  const target = norm(mealName);
  if (!target) return null;
  const exact = SOURCE_RECIPES.find((r) => norm(r.title) === target);
  if (exact) return exact;
  const words = target.split(" ").filter((w) => w.length > 3);
  if (!words.length) return null;
  let best = null;
  let bestScore = 0;
  for (const r of SOURCE_RECIPES) {
    const hay = norm(`${r.title} ${r.subtitle}`);
    const score = words.filter((w) => hay.includes(w)).length / words.length;
    if (score > bestScore) {
      best = r;
      bestScore = score;
    }
  }
  return bestScore >= 0.6 ? best : null;
}
